t.script:
(function () {
    var box = document.getElementById('docSearch');
    if (!box) { return; }
    var rows = Array.prototype.slice.call(document.querySelectorAll('#docList .doc'));
    box.addEventListener('input', function () {
        var q = box.value.trim().toLowerCase(), shown = 0;
        rows.forEach(function (r) {
            var hit = !q || r.getAttribute('data-q').indexOf(q) !== -1;
            r.style.display = hit ? '' : 'none';
            if (hit) { shown += 1; }
        });
        document.getElementById('docNone').style.display = (rows.length ? !shown : false) ? '' : 'none';
    });
})();

div.script:
(function () {
    var d = document.getElementById(location.hash.slice(1));
    if (d && d.tagName === 'DETAILS') {
        d.open = true;
        setTimeout(function () { d.scrollIntoView({behavior: 'smooth', block: 'start'}); }, 50);
    }
})();

(function () {
    var box = document.getElementById('completeBox');
    var f = box ? box.querySelector('form') : null;
    if (!f) { return; }
    var btn = f.querySelector('.js-finish-btn');
    function apply() {
        var picked = f.querySelector('input[name=finish_mode]:checked');
        var partial = picked ? picked.value === 'partial' : false;
        f.classList.toggle('is-partial', partial);
        btn.value = partial ? 'partial' : 'full';
        btn.textContent = partial ? '🏁 Send partial finish' : 'Submit for approval';
    }
    Array.prototype.forEach.call(f.querySelectorAll('input[name=finish_mode]'), function (r) {
        r.addEventListener('change', apply);
    });
    var h = location.hash;
    if (h === '#partial' || h === '#complete') {
        f.querySelector('input[name=finish_mode][value=' + (h === '#partial' ? 'partial' : 'full') + ']').checked = true;
        box.open = true;
        setTimeout(function () { box.scrollIntoView({behavior: 'smooth', block: 'start'}); }, 50);
    }
    apply();
})();

t.script:
(function () {
    var LINK = /^(https?:\/\/)?([\w-]+\.)+[a-z]{2,}(:\d+)?([\/?#]\S*)?$/i;
    var GITHUB = /^(https?:\/\/)?(www\.)?github\.com\/\S+/i;
    var DOCS = /\.(pdf|docx?)$/i;
    function val(f, n) { var el = f.elements[n]; return el ? String(el.value || '').trim() : ''; }
    function words(s) { return s.split(/[\s,]+/).filter(function (x) { return !!x; }); }
    function flash(f, kind, text) {
        var box = f.querySelector('.flash');
        if (!box) { box = document.createElement('div'); f.insertBefore(box, f.firstChild); }
        box.className = 'flash ' + kind;
        box.textContent = (kind === 'ok' ? '✅ ' : '⚠ ') + text;
        box.scrollIntoView({behavior: 'smooth', block: 'center'});
    }
    function check(f, mode) {
        var kind = f.getAttribute('data-kind'), partial = mode === 'partial';
        if (kind === 'time') {
            if (!(Number(val(f, 'hours')) || Number(val(f, 'minutes')))) { return 'Pick how much more time — hours, minutes or both.'; }
            if (!val(f, 'reason')) { return 'Write why you need more time — it is shown on the task card.'; }
            return '';
        }
        var maxMb = Number(f.getAttribute('data-max-mb') || 50);
        var hasUpdate = !!f.getAttribute('data-has-update');
        var hasManual = !!f.getAttribute('data-has-manual');
        var input = f.elements.files;
        var files = input ? Array.prototype.slice.call(input.files || []) : [];
        var summary = val(f, 'summary'), links = words(val(f, 'links'));
        var gh = val(f, 'gh_url'), branch = val(f, 'gh_branch');
        var bad = links.filter(function (l) { return !LINK.test(l); })[0];
        if (bad) { return '“' + bad + '” is not a valid link (e.g. https://example.com).'; }
        if (gh) {
            if (!GITHUB.test(gh)) { return 'Please enter a valid GitHub URL (must start with https://github.com/).'; }
            if (!branch || /\s/.test(branch)) { return 'Please enter a branch name (no spaces).'; }
        }
        // A full Complete's missing items are listed together by missing().
        var entry = f.getAttribute('data-entry') || '';
        if (kind === 'edit' ? (entry === 'progress' ? !summary : false) : false) {
            return 'The update text cannot be empty.';
        }
        if (kind === 'update' ? !summary : (kind === 'complete' ? (partial ? !(summary || hasUpdate) : false) : false)) {
            return 'Write a summary of what you did — this is what your manager reads.';
        }
        if (kind === 'complete' ? (!summary ? !!(links.length || gh) : false) : false) {
            return 'Write a summary to go with the links.';
        }
        var docOnly = kind === 'manual' || kind === 'complete' || (kind === 'edit' ? entry === 'manual' : false);
        if (!partial) {
            var big = files.filter(function (x) { return x.size > maxMb * 1048576; })[0];
            if (big) { return '“' + big.name + '” is over ' + maxMb + ' MB.'; }
            var notDoc = docOnly ? files.filter(function (x) { return !DOCS.test(x.name); })[0] : null;
            if (notDoc) { return '“' + notDoc.name + '” is not a PDF, DOC or DOCX file.'; }
        }
        if (kind === 'manual' ? !files.length : false) { return 'Choose the manual file (PDF, DOC or DOCX).'; }
        return '';
    }
    // Everything a full Complete still needs, all at once: [{text, el}].
    // data-need: what this task's type still needs (server rules).
    function missing(f) {
        var out = [], el = f.elements;
        var need = (f.getAttribute('data-need') || '').split(',');
        var has = function (k) { return need.indexOf(k) > -1; };
        var input = el.files, nFiles = input ? input.files.length : 0;
        if (has('summary') ? !(val(f, 'summary') || f.getAttribute('data-has-update')) : false) {
            out.push({text: 'A summary of what you did', el: el.summary});
        }
        if (has('manual') ? !(nFiles || val(f, 'user_manual_url')) : false) {
            out.push({text: 'The user manual (a PDF, DOC or DOCX file, or a link)', el: input});
        }
        if (has('github') ? !val(f, 'gh_url') : false) {
            out.push({text: 'The GitHub link + branch (this is a Module / App task)', el: el.gh_url});
        }
        [['app_link', 'app_link', 'The app link'], ['db_url', 'provision_url', 'The database URL'],
         ['db_name', 'provision_db_name', 'The database name'], ['db_user', 'provision_username', 'The username'],
         ['db_password', 'provision_password', 'The password']].forEach(function (x) {
            if (has(x[0]) ? !val(f, x[1]) : false) { out.push({text: x[2], el: el[x[1]]}); }
        });
        return out;
    }
    function question(f, mode) {
        var kind = f.getAttribute('data-kind');
        if (kind === 'time') {
            var hh = Number(val(f, 'hours')), mm = Number(val(f, 'minutes'));
            return 'Add ' + (hh ? hh + 'h ' : '') + (mm ? mm + 'm' : '') + ' to the estimate?\n\nReason: ' + val(f, 'reason');
        }
        var input = f.elements.files, n = input ? input.files.length : 0;
        var bits = [];
        if (val(f, 'summary')) { bits.push('summary ✓'); }
        var nl = words(val(f, 'links')).length;
        if (nl) { bits.push(nl + ' link' + (nl === 1 ? '' : 's')); }
        if (n ? mode !== 'partial' : false) { bits.push(n + ' file' + (n === 1 ? '' : 's')); }
        if (val(f, 'gh_url')) { bits.push('GitHub ' + val(f, 'gh_url').replace(/^(https?:\/\/)?(www\.)?github\.com\//i, '') + ' (' + val(f, 'gh_branch') + ')'); }
        var what = bits.join(' · ');
        if (kind === 'delete') {
            return 'Delete ' + (f.getAttribute('data-what') || 'this') + '? This cannot be undone.';
        }
        if (kind === 'edit') {
            var drop = f.querySelectorAll('input[name=remove]:checked').length;
            var all = f.querySelectorAll('input[name=remove]').length;
            var head = f.getAttribute('data-entry') === 'manual' ? 'Save changes to this user manual?' : 'Save changes to this update?';
            var lose = drop ? '\n\n' + drop + ' file' + (drop === 1 ? '' : 's') + ' will be removed.' : '';
            if (f.getAttribute('data-entry') === 'manual' ? (drop === all ? (all ? !n : false) : false) : false) {
                lose += ' No file would be left, so the manual itself will be deleted.';
            }
            return head + '\n\n' + (what || 'text / links') + lose;
        }
        if (kind === 'update') { return 'Save this update?\n\n' + what; }
        if (kind === 'manual') { return 'Save this user manual?\n\n' + what; }
        var ref = f.getAttribute('data-ref') || 'this task';
        if (mode === 'partial') { return 'Send ' + ref + ' as a partial finish? The client is sent this summary.\n\n' + (val(f, 'summary') || 'Your last update is used as the summary.'); }
        if (val(f, 'provision_url')) { bits.push('database ' + (val(f, 'provision_db_name') || val(f, 'provision_url'))); }
        if (val(f, 'user_manual_url')) { bits.push('manual link'); }
        if (val(f, 'app_link')) { bits.push('app link'); }
        what = bits.join(' · ');
        // Recommended but not added (user manual, GitHub link): warn, never block.
        var warn = (f.getAttribute('data-warn') || '').split(' · ').filter(function (w) {
            if (!w) { return false; }
            if (/github/i.test(w)) { return !val(f, 'gh_url'); }
            if (/manual/i.test(w)) { return !(val(f, 'user_manual_url') || n); }
            return true;
        }).map(function (w) { return '• ' + w + ' — needed'; }).join('\n');
        return 'Submit ' + ref + ' for approval?' + (what ? '\n\n' + what : '')
            + (warn ? '\n\n⚠️ Not added — you can still complete:\n' + warn : '');
    }
    Array.prototype.forEach.call(document.querySelectorAll('form.js-send'), function (f) {
        var clicked = null;
        Array.prototype.forEach.call(f.querySelectorAll('button[type=submit]'), function (b) {
            b.addEventListener('click', function () { clicked = b; });
        });
        f.addEventListener('submit', function (e) {
            e.preventDefault();
            var btn = e.submitter || clicked || f.querySelector('button[type=submit]');
            var mode = btn ? (btn.getAttribute('value') || '') : '';
            var problem = check(f, mode);
            if (problem) { flash(f, 'err', problem); return; }
            var gaps = (f.getAttribute('data-kind') === 'complete' ? mode !== 'partial' : false) ? missing(f) : [];
            // Our own popup (static/src/wa_client_form/dialog.js), not the
            // browser's "… says" box. It answers later, so the send waits.
            var step = Promise.resolve(true);
            if (gaps.length) {
                // One popup naming everything still missing. A partial finish
                // is offered instead when there is a summary to send.
                var list = 'Before completing ' + (f.getAttribute('data-ref') || 'this task') + ' you still need:\n\n'
                    + gaps.map(function (g) { return '• ' + g.text; }).join('\n');
                var canPartial = !!(val(f, 'summary') || f.getAttribute('data-has-update'));
                step = (canPartial
                    ? window.kpiConfirm(list + '\n\nSend it as a Partial finish instead (summary only), or go back and add them?',
                                        {ok: 'Send as partial', cancel: 'Go back'})
                    : window.kpiAlert(list).then(function () { return false; })
                ).then(function (asPartial) {
                    if (!asPartial) {
                        flash(f, 'err', 'Still needed: ' + gaps.map(function (g) { return g.text; }).join(' · ') + '.');
                        if (gaps[0].el) { gaps[0].el.focus(); }
                        return false;
                    }
                    mode = 'partial';
                    return true;
                });
            }
            step.then(function (go) {
                return go ? window.kpiConfirm(question(f, mode), {ok: 'Yes, send'}) : false;
            }).then(function (go) { if (go) { send(); } });
            function send() {
            var data = new FormData(f);
            if (mode) { data.set('mode', mode); }
            if (mode === 'partial') { data.delete('files'); }
            var buttons = f.querySelectorAll('button');
            var label = btn ? btn.textContent : '';
            var bar = f.querySelector('.prog');
            if (!bar) { bar = document.createElement('div'); bar.className = 'prog'; bar.appendChild(document.createElement('i')); f.appendChild(bar); }
            bar.style.display = 'block';
            Array.prototype.forEach.call(buttons, function (b) { b.disabled = true; });
            function done() {
                Array.prototype.forEach.call(buttons, function (b) { b.disabled = false; });
                if (btn) { btn.textContent = label; }
                bar.style.display = 'none'; bar.firstChild.style.width = '0';
            }
            var xhr = new XMLHttpRequest();
            xhr.open('POST', f.getAttribute('action'));
            xhr.setRequestHeader('X-Requested-With', 'XMLHttpRequest');
            xhr.upload.onprogress = function (ev) {
                if (!ev.lengthComputable) { return; }
                var pct = Math.min(100, Math.round(ev.loaded * 100 / ev.total));
                bar.firstChild.style.width = pct + '%';
                if (btn) { btn.textContent = pct === 100 ? 'Saving…' : 'Uploading ' + pct + '%'; }
            };
            xhr.onload = function () {
                var res = null;
                try { res = JSON.parse(xhr.responseText); } catch (err) { res = null; }
                done();
                if (!res) { flash(f, 'err', 'This link has expired. Tap 📋 KPI details in WhatsApp for a fresh one — what you filled in is still here.'); return; }
                if (!res.ok) { flash(f, 'err', res.message || 'Could not save that.'); return; }
                if (res.done_html) {
                    // Finished: the link is spent. Show the final Done page, and
                    // drop the page from history so Back does not reopen the form.
                    history.replaceState(null, '', window.location.pathname);
                    document.open(); document.write(res.done_html); document.close();
                    return;
                }
                flash(f, 'ok', res.message || 'Saved.');
                window.location.href = window.location.pathname + '?ok=' + encodeURIComponent(res.message || 'Saved.');
            };
            xhr.onerror = function () { done(); flash(f, 'err', 'Network problem — nothing was sent. Your entries are still here; try again.'); };
            xhr.send(data);
            }
        });
    });
})();

                    (function () {
                        var ov = document.getElementById('chat-ov'), list = document.getElementById('chat-list');
                        var input = document.getElementById('chat-in'), sendBtn = document.getElementById('chat-send');
                        var bar = document.getElementById('chat-bar'), info = document.getElementById('chat-info');
                        var pin = document.getElementById('chat-pin'), menu = document.getElementById('chat-menu');
                        var chips = document.getElementById('chat-chips'), replyBar = document.getElementById('chat-reply');
                        var prog = document.getElementById('chat-prog');
                        var scrim = document.getElementById('chat-scrim'), card = document.getElementById('chat-card');
                        var url = ov.getAttribute('data-url'), timer = null, shown = '';
                        var MAX_FILES = 10, MAX_BYTES = 50 * 1024 * 1024;
                        var QUICK = ['👍', '❤️', '😂', '😮', '😢', '🙏'];
                        var ALL = ['👍', '👎', '❤️', '🔥', '🎉', '👏', '🙏', '💯', '😂', '🤣', '😅', '😊', '😍', '😎', '🤔', '😐',
                                   '😮', '😢', '😭', '😡', '🥳', '🤝', '💪', '✅', '❌', '⚠️', '👀', '🚀', '⭐', '💡', '⏰', '📌'];
                        var picked = [], replyTo = null, editing = null, sending = false, rowsNow = [], canAct = false, canSend = false;
                        var ICON = { image: '📷', video: '🎥', audio: '🎵', document: '📄' };
                        function el(tag, cls, text) { var e = document.createElement(tag); if (cls) { e.className = cls; } if (text) { e.textContent = text; } return e; }
                        function when(at) { return at ? new Date(at.replace(' ', 'T') + 'Z') : null; }
                        function dayOf(d) {
                            var k = d.toDateString();
                            if (k === new Date().toDateString()) { return 'Today'; }
                            if (k === new Date(Date.now() - 86400000).toDateString()) { return 'Yesterday'; }
                            return d.toLocaleDateString([], { day: 'numeric', month: 'short', year: 'numeric' });
                        }
                        function clock(d) { return d ? d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : ''; }
                        function stamp(at) { var d = when(at); return d ? (dayOf(d) === 'Today' ? '' : dayOf(d) + ' ') + clock(d) : 'not yet'; }
                        function size(n) {
                            n = n || 0;
                            if (n < 1024) { return n + ' B'; }
                            if (n < 1048576) { return (n / 1024).toFixed(0) + ' KB'; }
                            return (n / 1048576).toFixed(1) + ' MB';
                        }
                        function kindOf(f) {
                            var t = (f.type || '').toLowerCase(), n = (f.name || '').toLowerCase();
                            if (t.indexOf('audio/') === 0) { return 'audio'; }
                            if (t.indexOf('image/') === 0) { return 'image'; }
                            if (t.indexOf('video/') === 0) { return 'video'; }
                            if (/\.(jpe?g|png|gif|webp|bmp|heic|heif)$/.test(n)) { return 'image'; }
                            if (/\.(mp4|mov|mkv|avi|m4v)$/.test(n)) { return 'video'; }
                            if (/\.(webm|ogg|opus|mp3|wav|m4a|aac|amr|3gp)$/.test(n)) { return 'audio'; }
                            if (/\.(pdf|docx?|xlsx?|pptx?|odt|ods|odp|rtf|txt|csv|zip|rar|7z)$/.test(n)) { return 'document'; }
                            return '';
                        }
                        function filesLabel(files) {
                            var out = [];
                            [['image', 'photo', 'photos'], ['video', 'video', 'videos'], ['audio', 'audio', 'audios'], ['document', 'document', 'documents']].forEach(function (k) {
                                var n = (files || []).filter(function (f) { return f.kind === k[0]; }).length;
                                if (n) { out.push(ICON[k[0]] + ' ' + n + ' ' + (n === 1 ? k[1] : k[2])); }
                            });
                            return out.join(' · ');
                        }
                        function whoOf(m) { return m.side === 'team' ? m.who : m.who + ' · client'; }
                        function say(msg) { if (window.kpiAlert) { window.kpiAlert(msg); } else { alert(msg); } }
                        function media(f, r) {
                            var box = el('div', 'chat-file'), m;
                        if (f.kind === 'document') {
                            m = el('a'); m.href = f.url; m.target = '_blank'; m.rel = 'noopener';
                            m.style.cssText = 'display:flex;gap:8px;align-items:center;padding:10px 12px;background:rgba(0,0,0,.05);border-radius:6px;color:inherit;text-decoration:none;word-break:break-all;min-width:200px';
                            m.appendChild(el('span', '', '📄')); m.appendChild(el('b', '', f.name));
                            box.appendChild(m); box.appendChild(el('div', 'chat-fname', size(f.size)));
                            return box;
                        }
                            if (f.kind === 'image') {
                                m = el('img'); m.src = f.url; m.alt = f.name; m.loading = 'lazy';
                                m.addEventListener('click', function () { viewPhoto(f, r); });
                                box.appendChild(m);
                            } else {
                                m = el(f.kind === 'video' ? 'video' : 'audio');
                                m.src = f.url; m.controls = true; m.preload = 'metadata';
                                box.appendChild(m);
                            }
                            box.appendChild(el('div', 'chat-fname', f.name + ' · ' + size(f.size)));
                            return box;
                        }
                        // Tap a photo: full screen over the chat, as in WhatsApp. ✕, a tap
                        // outside the photo or Esc closes it.
                        // r: the message it came in. Who sent it and when on top; its words under
                        // the photo, as in WhatsApp.
                        function pvHead(f, r) {
                            var h = el('span', 'pv-name'), t = r ? when(r.at) : null;
                            h.appendChild(el('b', '', (r ? r.who : '') || f.name));
                            if (t) { h.appendChild(el('small', '', (dayOf(t) === 'Today' ? 'Today' : dayOf(t)) + ' at ' + clock(t))); }
                            return h;
                        }
                        function viewPhoto(f, r) {
                            var v = el('div', 'pv-shade'), img = el('img'), bar = el('div', 'pv-bar'), x = el('button', 'pv-x', '✕');
                            var dl = el('a', 'pv-dl', '⤓'); dl.href = f.url; dl.target = '_blank'; dl.title = 'Open / download';
                            x.type = 'button'; x.title = 'Close';
                            bar.appendChild(pvHead(f, r)); bar.appendChild(dl); bar.appendChild(x);
                            img.src = f.url; img.alt = f.name;
                            v.appendChild(bar); v.appendChild(img);
                            if (r ? r.body : '') { v.appendChild(el('div', 'pv-cap', r.body)); }
                            function shut() { document.removeEventListener('keydown', key); if (v.parentNode) { v.parentNode.removeChild(v); } }
                            function key(e) { if (e.key === 'Escape') { shut(); } }
                            x.addEventListener('click', shut);
                            v.addEventListener('click', function (e) { if (e.target === v) { shut(); } });
                            document.addEventListener('keydown', key);
                            document.body.appendChild(v);
                        }
                        function jump(id) {
                            var t = document.getElementById('chat-m' + id);
                            if (!t) { return; }
                            t.scrollIntoView({ block: 'center', behavior: 'smooth' });
                            t.classList.add('flash');
                            setTimeout(function () { t.classList.remove('flash'); }, 1400);
                        }
                        // Hold a bubble (or right-click) to open its actions, as in WhatsApp.
                        function holdable(node, id) {
                            var timer = null, sx = 0, sy = 0, fired = false, firedAt = 0;
                            function clear() { if (timer) { clearTimeout(timer); timer = null; } }
                            function start(x, y) { sx = x; sy = y; fired = false; clear(); timer = setTimeout(function () { timer = null; fired = true; firedAt = Date.now(); openCard(id); }, 450); }
                            function moved(x, y) { if (timer && (Math.abs(x - sx) > 8 || Math.abs(y - sy) > 8)) { clear(); } }
                            // Touch first: a phone may cancel pointer events mid-press, touch events it keeps.
                            node.addEventListener('touchstart', function (e) { var t = e.touches[0]; if (t) { start(t.clientX, t.clientY); } }, { passive: true });
                            node.addEventListener('touchmove', function (e) { var t = e.touches[0]; if (t) { moved(t.clientX, t.clientY); } }, { passive: true });
                            node.addEventListener('touchend', function (e) { clear(); if (fired) { e.preventDefault(); } });
                            node.addEventListener('touchcancel', clear);
                            node.addEventListener('mousedown', function (e) { if (e.button === 0 && !('ontouchstart' in window)) { start(e.clientX, e.clientY); } });
                            node.addEventListener('mousemove', function (e) { moved(e.clientX, e.clientY); });
                            ['mouseup', 'mouseleave'].forEach(function (n) { node.addEventListener(n, clear); });
                            // A phone's own long-press menu comes right after our hold: ignore that one.
                            node.addEventListener('contextmenu', function (e) { e.preventDefault(); clear(); if (Date.now() - firedAt > 800) { openCard(id); } });
                        }
                        function reactionChips(m) {
                            if (!m.reactions || !m.reactions.length) { return null; }
                            var row = el('div', 'chat-react');
                            m.reactions.forEach(function (x) {
                                var c = el('button', 'chat-rchip' + (x.mine ? ' mine' : ''), x.emoji + (x.count > 1 ? ' ' + x.count : ''));
                                c.type = 'button'; c.title = x.mine ? 'You reacted — tap to remove' : 'Tap to react';
                                c.addEventListener('click', function () { if (canAct) { act(m.id, 'react', { emoji: x.emoji }); } });
                                row.appendChild(c);
                            });
                            return row;
                        }
                        // 🔔 A message from the other side while this tab is in the background (or
                        // the window is not focused): a soft pop and "(N) New message" in the tab
                        // title, cleared when the person comes back. Looking at the chat: silent.
                        var notify = (function () {
                            var ctx = null, unread = 0, base = document.title;
                            function unlock() {
                                if (!ctx) { try { ctx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { ctx = null; } }
                                if (ctx && ctx.state === 'suspended') { ctx.resume(); }
                            }
                            ['pointerdown', 'keydown', 'touchstart'].forEach(function (n) { document.addEventListener(n, unlock, { passive: true }); });
                            function pop() {
                                if (!ctx) { return; }
                                var t = ctx.currentTime;
